examples.source:
@startuml
|User|
start
:Submit form;
|System|
if (valid?) then (yes)
  :Save;
else (no)
  :Reject;
  stop
endif
repeat
  :Notify;
repeat while (retry?) is (yes)
stop
@enduml

@startuml
[*] --> Idle
state "Running mode" as r1 {
  [*] --> Warm
  Warm --> Hot : load
}
state c <<choice>>
Idle --> r1 : start
r1 --> c
c --> Idle : [ok]
c --> [*] : [fail]
Idle : waits for jobs
@enduml

@startuml
left to right direction
actor Customer
actor "Shop Admin" as adm
rectangle Shop {
  usecase "Place order" as UC1
  usecase "Pay" as UC2
  (Refund) as UC3
  Customer --> UC1
  UC1 .> UC2 : include
  adm --> UC3
}
@enduml

@startuml
package "Backend" {
  [Auth API] --> [Users DB] : sql
}
interface REST
[Auth API] - REST
node Server {
  artifact app.jar
}
cloud Net
database PG
Server --> PG
Server -- Net
@enduml

@startuml
concise "Web" as W
robust "DB" as D
clock clk with period 50
@0
W is Idle
D is Ready
@100
W is Busy
D is Busy
@300
W is Idle
@enduml

@startuml
hide empty members
class "Engine" as e0002 <<Entity>> {
  +rpm : int
  -start()
}
abstract class "Part" as e0001
interface Drawable
e0001 <|-- e0002
e0002 *-- "2..*" Wheel
e0002 ..> Drawable
note right of e0002 : id is the alias
@enduml
